#!/usr/bin/env python3
"""Apply the reviewed strict prompt.registry V4 storage patch idempotently."""

from __future__ import annotations

import base64
import subprocess
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PATCH_SHA256 = "6eec2f2c5ccc186c34f0c9d11a4b02fca9065f42b0d6ef5cb0aeb89c3876a3db"
PATCH_B64 = """ hzdG9yZWQpKSA9PiAobWlncmF0ZV92MihzdG9yZWQsIG1heGltdW1fcmVjb3Jkcyk/LCB0cnVlKSwKKyAgICAgICAgICAgIFNvbWUoU3RvcmVkQW55OjpWMS """


def run(*args: str) -> subprocess.CompletedProcess[bytes]:
    return subprocess.run(
        args,
        cwd=ROOT,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )


def main() -> None:
    patch = base64.b64decode(PATCH_B64)
    import hashlib
    if hashlib.sha256(patch).hexdigest() != PATCH_SHA256:
        raise SystemExit("embedded prompt.registry V4 patch digest mismatch")
    with tempfile.NamedTemporaryFile(prefix="prompt-registry-v4-", suffix=".patch") as file:
        file.write(patch)
        file.flush()
        path = file.name
        reverse = run("git", "apply", "--reverse", "--check", path)
        if reverse.returncode == 0:
            return
        check = run("git", "apply", "--check", path)
        if check.returncode != 0:
            raise SystemExit(
                "reviewed prompt.registry V4 patch no longer applies:\n"
                + check.stderr.decode("utf-8", errors="replace")
            )
        applied = run("git", "apply", path)
        if applied.returncode != 0:
            raise SystemExit(applied.stderr.decode("utf-8", errors="replace"))


if __name__ == "__main__":
    main()
